xt": "801a2da2-6b0e-434f-acc2-69d29744b0db"}, "cbc:ContractFolderID": "53b9a5ce-191a-4155-9c0c-69afd5db9043", "cbc:IssueDate": "2024-07-18+02:00", "cbc:IssueTime": "14:07:49+02:00", "cbc:VersionID": "01", "cbc:RegulatoryDomain": "32014L0024", "cbc:NoticeTypeCode": {"@listName": "competition", "#text": "cn-standard"}, "cbc:NoticeLanguageCode": "FRA", "cac:ContractingParty": {"cbc:BuyerProfileURI": "https://www.e-marchespublics.com/", "cac:ContractingPartyType": {"cbc:PartyTypeCode": {"@listName": "buyer-legal-type", "#text": "la"}}, "cac:ContractingActivity": {"cbc:ActivityTypeCode": {"@listName": "authority-activity", "#text": "gen-pub"}}, "cac:Party": {"cac:PartyIdentification": {"cbc:ID": {"@schemeName": "organization", "#text": "ORG-0001"}}}}, "cac:TenderingTerms": {"cac:TendererQualificationRequest": {"cac:SpecificTendererRequirement": {"cbc:TendererRequirementTypeCode": {"@listName": "exclusion-ground", "#text": "nati-ground"}, "cbc:Description": {"@languageID": "FRA", "#text": "(voir DUME ou DC1-DC2)"}}}}, "cac:TenderingProcess": {"cbc:ProcedureCode": {"@listName": "procurement-procedure-type", "#text": "oth-single"}}, "cac:ProcurementProject": {"cbc:ID": {"@schemeName": "InternalID", "#text": "PPP1VS-46/4031/2024-10"}, "cbc:Name": {"@languageID": "FRA", "#text": "Fourniture et élaboration de repas et goûters pour les services enfance et petite enfance de la ville de Saint-Julien de Concelles"}, "cbc:Description": {"@languageID": "FRA", "#text": "Le présent marché a pour objet la fourniture et l'élaboration de repas (cuisine réalisée sur place avec mise en place de personnel) pour la restauration en self service et à table : de l’école élémentaire Le Lys de la Vallée (pôle restauration), de l’école maternelle et élémentaire privée Gabriel Deshayes (pôle restauration) , de l’école maternelle Le Lys de la Vallée (liaison chaude) , de l’accueil de loisirs sans hébergement (pôle restauration), du multi-accueil de la commune (liaison chaude et liaison froide).

Les goûters pour les services suivants seront à fournir : à l’accueil périscolaire situé à l’école élémentaire du Lys de la Vallée, à l’accueil périscolaire situé au P’tit campus, à l'accueil de loisirs à l’école du Lys de la Vallée élémentaire ou maternelle, à l’accueil de loisirs sans hébergement situé au P’tit campus, au multi-accueil situé au P’tit Campus, livraison en même temps que les repas à 11h"}, "cbc:ProcurementTypeCode": {"@listName": "contract-nature", "#text": "supplies"}, "cac:RequestedTenderTotal": {"cbc:EstimatedOverallContractAmount": {"@currencyID": "EUR", "#text": "430000.00"}}, "cac:MainCommodityClassification": {"cbc:ItemClassificationCode": {"@listName": "cpv", "#text": "15894210"}}}, "cac:ProcurementProjectLot": {"cbc:ID": {"@schemeName": "Lot", "#text": "LOT-0001"}, "cac:TenderingTerms": {"ext:UBLExtensions": {"ext:UBLExtension": {"ext:ExtensionContent": {"efext:EformsExtension": {"efac:SelectionCriteria": [{"cbc:CriterionTypeCode": {"@listName": "selection-criterion", "#text": "tp-abil"}, "cbc:Description": {"@languageID": "FRA", "#text": "Le candidat devra fournir :
- une liste des références détaillées de moins de trois ans pour des prestations similaires
- les certificats de système qualité (ISO, HACCP,…)
- les pouvoirs de délégation de signature du candidat si nécessaire
- les attestations d'assurance à jour couvrant les responsabilités civiles et professionnelles
- tout autre document jugé utile et permettant à l'acheteur public d'apprécier les capacités professionnelles, techniques 
et financières du candidat"}}, {"cbc:CriterionTypeCode": {"@listName": "selection-criterion", "#text": "ef-stand"}, "cbc:Description": {"@languageID": "FRA", "#text": "Le candidat devra fournir les justifications à produire prévues aux articles R 2143-1 à R 2143-14  du Code de la Commande publique.
- Lettre de candidature (modèle DC1)
- Déclaration sur l'honneur et/ou les attestations correspondantes, à savoir :
- ne pas avoir fait l'objet, depuis moins de cinq ans, d'une condamnation définitive pour l'une des infractions prévues par le Code Pénal ou ne pas avoir fait l'objet d'une condamnation pour une infraction de même nature dans un autre État de l'Union Européenne ;
